def c3d_outputs(params: C3d, execution: Execution) -> C3dOutputs:
    """Build the C3dOutputs object for this tool."""
    output_v: list[OutputPathType] = []
    root_v: OutputPathType = execution.output_file(".")
    for __o0 in params["operations"]:
        if __o0["@type"] == "output":
            output_v.append(execution.output_file(__o0["output"]))
    return C3dOutputs(
        root=root_v,
        output=output_v,
    )

def c3d_execute(params: C3d, runner: Runner | None = None) -> C3dOutputs:
    """
    c3d

    C3D is a command-line tool for medical image processing.

    Author: Convert3D Developers

    URL: http://www.itksnap.org/pmwiki/pmwiki.php?n=Convert3D.Convert3D

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    c3d_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(C3D_METADATA)
    execution.params(params)
    args = c3d_cargs(params, execution)
    out = c3d_outputs(params, execution)
    execution.run(args)
    return out

def c3d(
    input_: list[InputPathType],
    operations: list[C3dOperations],
    output: str,
    runner: Runner | None = None,
) -> C3dOutputs:
    """
    c3d

    C3D is a command-line tool for medical image processing.

    Author: Convert3D Developers

    URL: http://www.itksnap.org/pmwiki/pmwiki.php?n=Convert3D.Convert3D

    Args:
        input_: The input image to process.
        operations: The operations to perform.
        output: The output image.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    params = c3d_params(
        input_=input_,
        operations=operations,
        output=output,
    )
    return c3d_execute(params, runner)

